# PS6 settings: read a TOML settings file and check every value. Students do not edit this file.
#
# A TOML file holds one setting per line, written as name = value, such as seed = 5660. The checker
# reads config/defaults.toml, the graded settings, and explore.jl reads config/explore.toml. load_config
# checks every value, and stops with a one-sentence message that names the setting when a value is
# missing or not valid.
#
# The file reads from top to bottom:
#   1. config_setting   reads one setting that is a number or a text
#   2. config_list      reads one setting that is a list of texts
#   3. check_setting    stops with a message when a check fails
#   4. load_config      reads and checks every setting, and returns them as one NamedTuple
#   5. config_hash      computes the SHA-256 hash of a settings file
#
# Julia notes for this file:
#   settings[key]     reads the value of the setting named key from the parsed file, a Dict
#   value isa T       is true when value has the type T, such as Bool or Integer
#   T <: Number       is true when T is a number type, such as Float64 or Int
#   try ... catch     runs the code after try; when that code stops with an error, runs the code after catch
#   throw(...)        stops the program with an error message

# TOML reads the settings file, and SHA computes its hash -
using TOML, SHA

# The columns of the FRED file, data/fred-levels-2014-2024.csv: the only names that fred_series may hold -
const FRED_COLUMNS = ["DGS10", "T10YIE", "DCOILBRENTEU", "DTWEXBGS"];

# The 11 sectors of the Global Industry Classification Standard (GICS): the only names that pair_first
# and pair_second may hold -
const GICS_SECTORS = ["Communication Services", "Consumer Discretionary", "Consumer Staples", "Energy",
    "Financials", "Health Care", "Industrials", "Information Technology", "Materials", "Real Estate", "Utilities"];

"""
    config_setting(settings::Dict, key::String, T::Type)

Read one setting from a parsed TOML file and convert it to type `T`.

### Arguments

- `settings`: The parsed TOML file, from `TOML.parsefile`.
- `key`: The name of the setting.
- `T`: The type the setting must have, such as `Float64`, `Int`, or `String`.

### Returns

- The setting, converted to `T`.

### Errors

- An `ArgumentError` when the setting is missing or cannot be converted to `T`. An integer setting
  must be written as a whole number (`100`, not `100.0`).
"""
function config_setting(settings::Dict, key::String, T::Type)

    # Is the setting in the file? haskey checks whether the Dict has an entry named key -
    if !haskey(settings, key)
        throw(ArgumentError("Setting '$key' is missing from the config file."));
    end
    value = settings[key];

    # A number setting cannot be true or false. Julia treats true and false as numbers, so this check
    # comes first -
    if T <: Number && value isa Bool
        throw(ArgumentError("Setting '$key' must be a number, not true or false."));
    end

    # Integer settings must be written as whole numbers, such as 100 and not 100.0 -
    if T <: Integer && !(value isa Integer)
        throw(ArgumentError("Setting '$key' must be a whole number."));
    end

    # Convert the value to T, such as Float64(5) = 5.0. When the conversion fails, say what the setting
    # needs: a text setting, such as benchmark_ticker, needs quotes, and any other setting is a number -
    try
        return T(value);
    catch
        if T == String
            throw(ArgumentError("Setting '$key' must be text in quotes."));
        end
        throw(ArgumentError("Setting '$key' must be a number."));
    end
end

"""
    config_list(settings::Dict, key::String) -> Vector{String}

Read one list of text values from a parsed TOML file.

### Arguments

- `settings`: The parsed TOML file, from `TOML.parsefile`.
- `key`: The name of the setting.

### Returns

- The entries of the list, as a `Vector{String}`.

### Errors

- An `ArgumentError` when the setting is missing, is not a list, or has an entry that is not text in
  quotes.
"""
function config_list(settings::Dict, key::String)::Vector{String}

    # Is the setting in the file, and is it a list? A TOML list is written in square brackets, such as
    # ["DGS10", "T10YIE"] -
    if !haskey(settings, key) || !(settings[key] isa AbstractVector)
        throw(ArgumentError("Setting '$key' must be a list of text values in quotes."));
    end

    # Copy each entry, one at a time, into a new list of texts; every entry must be text -
    result = String[];
    for value ∈ settings[key]
        if !(value isa AbstractString)
            throw(ArgumentError("Setting '$key' must be a list of text values in quotes."));
        end
        push!(result, String(value));
    end
    return result;
end

"""
    check_setting(ok::Bool, message::String)

Stop with a one-sentence message when a setting fails a check.

### Arguments

- `ok`: `true` when the setting passes the check.
- `message`: The message to show when the setting fails the check.

### Errors

- An `ArgumentError` with `message` when `ok` is `false`.
"""
function check_setting(ok::Bool, message::String)

    # Stop with the message when the check fails, and do nothing when it passes -
    if !ok
        throw(ArgumentError(message));
    end
    return nothing;
end

"""
    load_config(path::AbstractString) -> NamedTuple

Read a TOML settings file and check every value. The file spells `ν`, `ϵ`, and `λ` as `nu`,
`epsilon`, and `lambda`.

### Arguments

- `path`: The location of the settings file, such as `config/defaults.toml`.

### Returns

- A `NamedTuple` with the fields:
  - `Δt`: One trading day, `1/steps_per_year` (yr).
  - `number_of_states`: The number of hidden states of each jump hidden Markov model.
  - `ν`: The degrees of freedom of the Student-t distribution of each hidden state.
  - `ϵ`: The probability that a jump episode starts on a given day.
  - `λ`: The mean length of a jump episode (trading days).
  - `number_of_paths`: The number of synthetic markets drawn from each model.
  - `seed`: The seed of the random numbers, so that every run draws the same synthetic markets.
  - `benchmark_ticker`: The ticker of the market, `"SPY"`.
  - `fred_series`: The FRED code of each economic factor, such as `"DGS10"`.
  - `fred_kinds`: How each FRED series becomes a daily factor: `"change"` or `"growth"`.
  - `fred_names`: The name of each FRED series in the report.
  - `pair_first` and `pair_second`: The pairs of sectors in the report. Pair `k` is `pair_first[k]`
    and `pair_second[k]`.

### Errors

- An `ArgumentError` with a one-sentence message when a setting is missing or not valid.
"""
function load_config(path::AbstractString)::NamedTuple

    # Read the file into a Dict of settings. A file that is not valid TOML, such as a line without an
    # equals sign, stops with one message instead of a long parser error -
    settings = nothing;
    try
        settings = TOML.parsefile(path);
    catch
        throw(ArgumentError("The config file could not be read as TOML."));
    end

    # Read each single setting with the type it must have -
    steps_per_year = config_setting(settings, "steps_per_year", Int);
    number_of_states = config_setting(settings, "number_of_states", Int);
    nu = config_setting(settings, "nu", Float64);
    epsilon = config_setting(settings, "epsilon", Float64);
    lambda = config_setting(settings, "lambda", Float64);
    number_of_paths = config_setting(settings, "number_of_paths", Int);
    seed = config_setting(settings, "seed", Int);
    benchmark_ticker = config_setting(settings, "benchmark_ticker", String);

    # Read each list setting -
    fred_series = config_list(settings, "fred_series");
    fred_kinds = config_list(settings, "fred_kinds");
    fred_names = config_list(settings, "fred_names");
    pair_first = config_list(settings, "pair_first");
    pair_second = config_list(settings, "pair_second");

    # Check the single settings. The market must be SPY, because the FRED file holds one row for each
    # trading day of SPY -
    check_setting(steps_per_year >= 1, "The steps_per_year must be at least 1.");
    check_setting(number_of_states >= 2, "The number_of_states must be at least 2.");
    check_setting(isfinite(nu) && nu > 0, "The nu must be a positive number.");
    check_setting(0 <= epsilon && epsilon <= 1, "The epsilon must be from 0 to 1.");
    check_setting(isfinite(lambda) && lambda > 0, "The lambda must be a positive number.");
    check_setting(number_of_paths >= 1, "The number_of_paths must be at least 1.");
    check_setting(benchmark_ticker == "SPY", "The benchmark_ticker must be \"SPY\", because the FRED file holds one row for each SPY price day.");

    # Check the FRED series: at least one series, each a column of the FRED file, each named only once, and
    # each with a kind and a name. unique removes repeated names, so a list with a repeat is longer than
    # its unique names -
    check_setting(!isempty(fred_series), "The fred_series list must name at least one series.");
    check_setting(length(unique(fred_series)) == length(fred_series), "Each series in fred_series must appear only once.");
    for series ∈ fred_series
        check_setting(series in FRED_COLUMNS, "Every entry of fred_series must be one of $(join(FRED_COLUMNS, ", ")).");
    end
    check_setting(length(fred_kinds) == length(fred_series),
        "The fred_kinds list must have one entry for each series in fred_series.");
    for kind ∈ fred_kinds
        check_setting(kind == "change" || kind == "growth", "Every entry of fred_kinds must be \"change\" or \"growth\".");
    end
    check_setting(length(fred_names) == length(fred_series),
        "The fred_names list must have one entry for each series in fred_series.");

    # Check the pairs of sectors: at least one pair, and each pair names two different GICS sectors.
    # Pair k is pair_first[k] and pair_second[k] -
    check_setting(!isempty(pair_first), "The pair_first list must name at least one sector.");
    check_setting(length(pair_second) == length(pair_first),
        "The pair_second list must have one sector for each sector in pair_first.");
    for k ∈ 1:length(pair_first)
        check_setting(pair_first[k] in GICS_SECTORS, "Every entry of pair_first must be a GICS sector, such as \"Utilities\".");
        check_setting(pair_second[k] in GICS_SECTORS, "Every entry of pair_second must be a GICS sector, such as \"Utilities\".");
        check_setting(pair_first[k] != pair_second[k], "Each pair in pair_first and pair_second must name two different sectors.");
    end

    # Return the settings by name, with the time step of one trading day, Δt = 1/steps_per_year (yr).
    # The file spells the Greek names nu, epsilon, and lambda; the returned NamedTuple uses ν, ϵ, and λ,
    # as in the lecture -
    return (Δt = 1.0 / steps_per_year, number_of_states = number_of_states, ν = nu, ϵ = epsilon, λ = lambda,
        number_of_paths = number_of_paths, seed = seed, benchmark_ticker = benchmark_ticker,
        fred_series = fred_series, fred_kinds = fred_kinds, fred_names = fred_names,
        pair_first = pair_first, pair_second = pair_second);
end

"""
    config_hash(path::AbstractString) -> String

Compute the SHA-256 hash of a settings file, so that a run records exactly which settings it used.

### Arguments

- `path`: The location of the settings file.

### Returns

- The SHA-256 hash of the file, as a string of 64 hexadecimal characters. Windows line endings are
  changed to Unix line endings first, so that a copy saved on Windows has the same hash.
"""
function config_hash(path::AbstractString)::String

    # Use the same line endings on every operating system, then hash the text. Any change to the file,
    # even one space, gives a different hash, so the checker can tell whether the graded file was edited -
    text = replace(read(path, String), "\r\n" => "\n");
    return bytes2hex(sha256(text));
end
